using System.Text.Json;
using Quiberon.Simulation;
using Xunit;

public class ArtilleryTests
{
    static Rules Ruleset()=>new(){CombatEnabled=true,MoraleEnabled=true,CavalryEnabled=true,ArtilleryEnabled=true,SpecialistsEnabled=true,Width=1400,Height=1000};
    static Regiment Unit(int id,string type,double x,double y=300,int army=0)=>new(id,army,type,Archetypes.Get(type),new(x,y),army==0?0:Math.PI);
    static BattleSimulation Battle(string type="artillery",TerrainMap? terrain=null)=>new([Unit(0,type,300),Unit(1,"infantry",620,army:1)],Ruleset(),terrain,17);
    static string Fixture(string name)=>Path.Combine(AppContext.BaseDirectory,"artillery_fixtures",name+".json");
    public static IEnumerable<object[]> Physics=>JsonDocument.Parse(File.ReadAllText(Fixture("physics"))).RootElement.EnumerateArray().Select(r=>new object[]{r.GetProperty("name").GetString()!,r.GetRawText()});
    public static IEnumerable<object[]> Stress=>JsonDocument.Parse(File.ReadAllText(Fixture("stress"))).RootElement.EnumerateArray().Select(r=>new object[]{r.GetProperty("name").GetString()!,r.GetRawText()});
    // Python stress references retain the legacy .75 m contact/release rule.
    [Theory,MemberData(nameof(Stress))]public void PythonCombinedArmsStressStatesAndRandomStreamMatch(string name,string json){using var d=JsonDocument.Parse(json);var definition=d.RootElement.GetProperty("input").Deserialize<ScenarioDefinition>(ScenarioJson.Options)!;var b=(definition with {MeleeDisengageDistance=.75}).Create();for(int i=0;i<700;i++){definition.IssueScheduled(b);b.Step();}using var actual=JsonDocument.Parse(JsonSerializer.Serialize(new{finalStates=b.Units.Select(u=>new{id=u.Id,position=u.Position,strength=u.Strength,morale=u.Morale,cohesion=u.Cohesion,state=u.State.ToString().ToLowerInvariant(),withdrawn=u.Withdrawn}),draws=b.Random.Draws},ScenarioJson.Options));CombatReferenceTests.Compare(d.RootElement.GetProperty("expected"),actual.RootElement,name);Assert.True(b.Metrics.ArtilleryShots>0 && b.Metrics.ProjectileHits>0);}
    [Fact]public void BallisticNormKeepsPythonIntegerSubstepBoundaries(){using var d=JsonDocument.Parse(File.ReadAllText(Fixture("norms")));foreach(var row in d.RootElement.EnumerateArray()){double length=ArtillerySystem.Length(new(row.GetProperty("x").GetDouble(),row.GetProperty("y").GetDouble()));Assert.Equal(row.GetProperty("length").GetDouble(),length);Assert.Equal(row.GetProperty("pieces").GetInt32(),(int)Math.Ceiling(length*.1/2));}}
    [Theory,MemberData(nameof(Physics))] public void UnchangedPythonProjectileTraceMatches(string name,string json)
    {
        using var d=JsonDocument.Parse(json);var root=d.RootElement;
        var def=JsonSerializer.Deserialize<ScenarioDefinition>(root.GetProperty("input").GetRawText(),ScenarioJson.Options)!;var b=def.Create();
        var initial=root.GetProperty("initial");var p=b.Artillery.Add(new(){OwnerId=0,Position=initial.GetProperty("position").Deserialize<Vec2>(ScenarioJson.Options),Velocity=initial.GetProperty("velocity").Deserialize<Vec2>(ScenarioJson.Options),Height=initial.GetProperty("height").GetDouble(),VerticalSpeed=initial.GetProperty("verticalSpeed").GetDouble()});
        foreach(var expected in root.GetProperty("frames").EnumerateArray())
        {
            b.Artillery.Update();
            var result=new{tick=expected.GetProperty("tick").GetInt32(),projectile=new{position=p.Position,velocity=p.Velocity,height=p.Height,verticalSpeed=p.VerticalSpeed,energy=p.Energy,age=p.Age,bounces=p.Bounces,hitIds=p.HitIds.Order().ToArray()},active=b.Artillery.Projectiles.Contains(p),strengths=b.Units.Select(u=>u.Strength),morale=b.Units.Select(u=>u.Morale),cohesion=b.Units.Select(u=>u.Cohesion),draws=b.Random.Draws};
            using var actual=JsonDocument.Parse(JsonSerializer.Serialize(result,ScenarioJson.Options));CombatReferenceTests.Compare(expected,actual.RootElement,name);
        }
    }
    [Theory][InlineData("open-shot")][InlineData("prussian-drill")][InlineData("rifle-engagement")][InlineData("woodland-specialists")][InlineData("grenadier-support")]
    public void CompletePythonBattleTraceMatches(string name)
    {
        using var document=JsonDocument.Parse(File.ReadAllText(Fixture(name+"-trace")));var root=document.RootElement;
        var data=root.GetProperty("input").Deserialize<ScenarioDefinition>(ScenarioJson.Options)!;var b=data.Create();var frames=new List<object>();
        while(true){if(data.SampleTicks.Contains(b.Tick))frames.Add(new{tick=b.Tick,units=b.Units.Select(u=>new{id=u.Id,position=u.Position,facing=u.Facing,strength=u.Strength,morale=u.Morale,cohesion=u.Cohesion,reloadLeft=u.ReloadLeft}).ToArray(),projectiles=b.Artillery.Snapshot()});if(b.Tick>=200)break;data.IssueScheduled(b);b.Step();}
        using var actual=JsonDocument.Parse(JsonSerializer.Serialize(new{frames,draws=b.Random.Draws},ScenarioJson.Options));CombatReferenceTests.Compare(root.GetProperty("frames"),actual.RootElement.GetProperty("frames"),name);Assert.Equal(root.GetProperty("draws").GetInt64(),b.Random.Draws);
    }
    [Theory][InlineData(48,6)][InlineData(24,3)][InlineData(1,1)][InlineData(0,0)]
    public void OperationalGunsFollowCrewStrength(int strength,int expected){var b=Battle();b.Units[0].Strength=strength;Assert.Equal(expected,b.Units[0].AvailableGuns);}
    [Fact]public void FiringIsPhysicalNotInstantDamageAndSnapshotsAreCopies(){var b=Battle();var target=b.Units[1];Assert.True(b.Combat.Fire(b.Units[0],target));Assert.Equal(240,target.Strength);var snapshot=b.Snapshot();var first=snapshot.Projectiles![0];var original=b.Artillery.Projectiles[0].Position;b.Artillery.Update();Assert.Equal(original,first.Position);Assert.NotEqual(first.Position,b.Artillery.Projectiles[0].Position);Assert.All(b.Events,e=>Assert.Equal(e.Tick*Rules.Dt,e.Time,8));}
    [Fact]public void SalvoHasStableIndependentIdsAndCrewSupportedGuns(){var b=Battle();b.Units[0].Strength=24;b.Artillery.Salvo(b.Units[0],b.Units[1]);Assert.Equal(3,b.Artillery.Projectiles.Count);Assert.Equal(new long[]{0,1,2},b.Artillery.Projectiles.Select(p=>p.Id));Assert.Equal(3,b.Artillery.Projectiles.Select(p=>p.Position).Distinct().Count());Assert.All(b.Artillery.Projectiles,p=>Assert.Equal(100,p.Velocity.Length,9));}
    [Fact]public void BallOverheadCannotDamageAndSweptShotCannotTunnel(){var b=Battle();var u=b.Units[1];var p=b.Artillery.Add(new(){OwnerId=0,Position=new(560,300),Velocity=new(1000,0),Height=30});b.Artillery.AdvancePiece(p,.1,false);Assert.Equal(240,u.Strength);p.Position=new(560,300);p.Height=1;p.HitIds.Clear();b.Artillery.AdvancePiece(p,.1,false);Assert.True(u.Strength<240);}
    [Fact]public void PenetratesMultipleFormationsButNeverDamagesSameFormationTwice(){var b=new BattleSimulation([Unit(0,"artillery",300),Unit(1,"infantry",430,army:1),Unit(2,"infantry",470,army:1)],Ruleset(),random:new TapeRandom(Enumerable.Repeat(.5,100).ToArray()));var p=b.Artillery.Add(new(){OwnerId=0,Position=new(400,300),Velocity=new(1000,0),Height=1});b.Artillery.AdvancePiece(p,.1,false);Assert.Equal(2,p.HitIds.Count);Assert.Equal(.5625,p.Energy,10);Assert.True(b.Units[1].Strength< b.Units[2].Strength);var old=b.Units[1].Strength;p.Position=new(400,300);p.Height=1;b.Artillery.AdvancePiece(p,.1,false);Assert.Equal(old,b.Units[1].Strength);}
    [Fact]public void FriendlyFireUsesSameDamageAndMoralePath(){var b=new BattleSimulation([Unit(0,"artillery",300),Unit(1,"infantry",430)],Ruleset());var p=b.Artillery.Add(new(){OwnerId=0,Position=new(400,300),Velocity=new(100,0),Height=1});b.Artillery.AdvancePiece(p,.3,false);Assert.True(b.Units[1].Strength<240);Assert.True(b.Units[1].Morale<85);Assert.Equal(1,b.Metrics.FriendlyFireHits);Assert.Contains(b.Events,e=>e.Kind=="friendly_fire");}
    [Fact]public void ReloadAndDeploymentBlockFiringWithoutResettingReload(){var b=Battle();var u=b.Units[0];Assert.True(b.Combat.Fire(u,b.Units[1]));Assert.False(b.Combat.Fire(u,b.Units[1]));Assert.Equal(19,u.ReloadLeft);u.ReloadLeft=0;u.Limbered=true;Assert.False(b.Combat.Fire(u,b.Units[1]));u.Limbered=false;u.SetupLeft=1;Assert.False(b.Combat.Fire(u,b.Units[1]));}
    [Fact]public void ExplicitTargetCanFireOverRidgeButAutomaticTargetNeedsPerception(){var b=Battle(terrain:new([new(450,300,20,100,40,true)]));Assert.False(b.Combat.Sight(b.Units[0],b.Units[1]).Visible);Assert.True(b.Combat.CanFire(b.Units[0],b.Units[1]));Assert.Null(b.Combat.SelectFireTarget(b.Units[0]));b.Issue(new(0,new(OrderKind.Attack,TargetId:1)));b.Step();Assert.True(b.Metrics.ArtilleryShots>0);}
    [Fact]public void HoldFireRetainsTargetAndResumeFires(){var b=Battle();b.Issue(new(0,new(OrderKind.Attack,TargetId:1)));b.Issue(new(0,new(OrderKind.HoldFire)));b.Step();Assert.Empty(b.Artillery.Projectiles);Assert.Equal(1,b.Units[0].Order.TargetId);b.Issue(new(0,new(OrderKind.ResumeFire)));b.Step();Assert.NotEmpty(b.Artillery.Projectiles);}
    [Fact]public void SlowShotsTerminateAndNoStaleShotsRemainAfterVictory(){var b=Battle();var p=b.Artillery.Add(new(){OwnerId=0,Position=new(320,300),Height=.01,VerticalSpeed=-1,Velocity=new(5,0)});for(int i=0;i<150;i++)b.Artillery.Update();Assert.Empty(b.Artillery.Projectiles);b.Artillery.Launch(b.Units[0],b.Units[1]);b.Units[1].State=MoraleState.Routing;for(int i=0;i<140;i++)b.Step();Assert.NotNull(b.Result);Assert.Empty(b.Artillery.Projectiles);}
    [Fact]public void HorseBatteryMovesAndRedeploysFaster(){var b=new BattleSimulation([Unit(0,"artillery",300,200),Unit(1,"french_horse_artillery",300,500)],Ruleset());b.Issue(new(0,new(OrderKind.Move,new(340,200))));b.Issue(new(1,new(OrderKind.Move,new(340,500))));int[] ready=[0,0];for(int i=1;i<500;i++){b.Step();for(int j=0;j<2;j++)if(ready[j]==0 && b.Units[j].Position.X>=339 && !b.Units[j].Limbered)ready[j]=i;}Assert.True(ready[1]>0 && ready[0]>ready[1]+50);Assert.Contains(b.Events,e=>e.Kind=="battery_deployed");}
    [Fact]public void ProjectileImpactCanCauseRoutAndCascade(){var b=new BattleSimulation([Unit(0,"artillery",300),Unit(1,"infantry",430,army:1),Unit(2,"infantry",430,370,1)],Ruleset());b.Units[1].Morale=24;var p=b.Artillery.Add(new(){OwnerId=0,Position=new(400,300),Velocity=new(100,0),Height=1});b.Artillery.AdvancePiece(p,.3,false);b.MoraleSystem.Update();Assert.Equal(MoraleState.Routing,b.Units[1].State);Assert.True(b.Metrics.CascadeShocks>0);}
    [Theory][InlineData("open-shot")][InlineData("ricochet")][InlineData("artillery-hills")][InlineData("friendly-fire")][InlineData("enfilade")][InlineData("battery-under-attack")][InlineData("prussian-drill")][InlineData("woodland-specialists")][InlineData("grenadier-support")][InlineData("uhlan-charge")][InlineData("rifle-engagement")][InlineData("horse-redeployment")][InlineData("combined-arms")]
    public void EveryNewScenarioIsDeterministicAndFinite(string id){string Run(){var d=CombatScenarios.Get(id);var b=d.Create();for(int i=0;i<700 && b.Result is null;i++){d.IssueScheduled(b);b.Step();}Assert.All(b.Units,u=>{Assert.True(u.Position.Finite);Assert.InRange(u.Strength,0,u.MaximumStrength);Assert.InRange(u.Morale,0,100);Assert.InRange(u.Cohesion,0,100);});return JsonSerializer.Serialize(new{state=b.Snapshot(),metrics=b.Metrics,draws=b.Random.Draws,events=b.Events},ScenarioJson.Options);}Assert.Equal(Run(),Run());}
}
